create table if not exists maintenance_asset_categories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists maintenance_asset_prefixes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),category_id uuid not null references maintenance_asset_categories(id),prefix varchar(5) not null,name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,prefix),check(prefix ~ '^[A-Z]{2,5}$'));
create table if not exists maintenance_component_prefixes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),prefix varchar(4) not null,name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,prefix),check(prefix ~ '^[A-Z]{2,4}$'));
create table if not exists maintenance_asset_code_sequences(organization_id uuid not null references organizations(id),prefix varchar(5) not null,last_number integer not null default 0 check(last_number>=0),updated_at timestamptz not null default now(),primary key(organization_id,prefix));
create table if not exists maintenance_component_code_sequences(organization_id uuid not null references organizations(id),parent_asset_id uuid not null references maintenance_assets(id),component_prefix varchar(4) not null,last_number integer not null default 0 check(last_number>=0),updated_at timestamptz not null default now(),primary key(organization_id,parent_asset_id,component_prefix));
alter table maintenance_assets add column if not exists asset_name text;alter table maintenance_assets add column if not exists category_id uuid references maintenance_asset_categories(id);alter table maintenance_assets add column if not exists prefix_id uuid references maintenance_asset_prefixes(id);alter table maintenance_assets add column if not exists parent_asset_id uuid references maintenance_assets(id);alter table maintenance_assets add column if not exists manufacturer text;alter table maintenance_assets add column if not exists model text;alter table maintenance_assets add column if not exists serial_number text;alter table maintenance_assets add column if not exists description text;alter table maintenance_assets add column if not exists installation_date date;alter table maintenance_assets add column if not exists purchase_date date;alter table maintenance_assets add column if not exists purchase_cost numeric(12,2);alter table maintenance_assets add column if not exists warranty_expiry date;alter table maintenance_assets add column if not exists installed_at timestamptz;alter table maintenance_assets add column if not exists removed_at timestamptz;alter table maintenance_assets add column if not exists installed_work_order_id uuid references maintenance_work_orders(id);alter table maintenance_assets add column if not exists removed_work_order_id uuid references maintenance_work_orders(id);update maintenance_assets set asset_name=name where asset_name is null;alter table maintenance_work_orders add column if not exists component_asset_id uuid references maintenance_assets(id);
do $$declare o uuid;begin for o in select id from organizations loop insert into maintenance_asset_categories(organization_id,name) select o,x from unnest(array['DTG Printer','Tunnel Dryer','UV Printer','Roll Printer','Laminator','Cutter','Laser','Compressor','Screen Print Line','Conveyor','Exhaust / Ventilation','Compressed Air Equipment','Electrical Equipment','Other'])x on conflict do nothing;insert into maintenance_asset_prefixes(organization_id,category_id,prefix,name) select o,c.id,v.p,v.n from (values('DTG','DTG Printer'),('DRY','Tunnel Dryer'),('UVP','UV Printer'),('RLP','Roll Printer'),('LAM','Laminator'),('CUT','Cutter'),('LAS','Laser'),('CMP','Compressor'),('SCR','Screen Print Line'),('CON','Conveyor'),('EXH','Exhaust / Ventilation'),('AIR','Compressed Air Equipment'),('ELE','Electrical Equipment'),('OTH','Other'))v(p,n) join maintenance_asset_categories c on c.organization_id=o and c.name=v.n on conflict do nothing;insert into maintenance_component_prefixes(organization_id,prefix,name) values(o,'PH','Printhead'),(o,'PMP','Pump'),(o,'FLT','Filter Assembly'),(o,'SEN','Sensor'),(o,'MTR','Motor'),(o,'BRG','Bearing Assembly'),(o,'BLT','Belt'),(o,'FAN','Fan'),(o,'BRN','Burner'),(o,'ELC','Electronic Board / Module'),(o,'PSW','Pressure Switch'),(o,'VAL','Valve'),(o,'CYL','Cylinder'),(o,'ENC','Encoder'),(o,'PSU','Power Supply') on conflict do nothing;end loop;end$$;
create or replace function maintenance_create_asset(p_organization_id uuid,p_prefix_id uuid,p_name text,p_location text,p_manufacturer text,p_model text,p_serial_number text,p_description text,p_criticality text,p_status text,p_installation_date date,p_purchase_date date,p_purchase_cost numeric,p_warranty_expiry date,p_actor_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare p text;c uuid;n integer;code text;a uuid;begin if not exists(select 1 from maintenance_members where organization_id=p_organization_id and user_id=p_actor_id and active and role in('admin','maintenance'))then raise exception'Maintenance permission denied';end if;select prefix,category_id into p,c from maintenance_asset_prefixes where id=p_prefix_id and organization_id=p_organization_id and active for share;if p is null then raise exception'Invalid or inactive asset prefix';end if;insert into maintenance_asset_code_sequences values(p_organization_id,p,0,now())on conflict do nothing;update maintenance_asset_code_sequences set last_number=last_number+1,updated_at=now()where organization_id=p_organization_id and prefix=p returning last_number into n;if n>999 then raise exception'Asset sequence exhausted';end if;code:=p||'-'||lpad(n::text,3,'0');insert into maintenance_assets(organization_id,asset_code,name,asset_name,category_id,prefix_id,location,manufacturer,model,serial_number,description,criticality,status,installation_date,purchase_date,purchase_cost,warranty_expiry,installed_at,created_by)values(p_organization_id,code,p_name,p_name,c,p_prefix_id,nullif(trim(p_location),''),nullif(trim(p_manufacturer),''),nullif(trim(p_model),''),nullif(trim(p_serial_number),''),nullif(trim(p_description),''),p_criticality,p_status,p_installation_date,p_purchase_date,p_purchase_cost,p_warranty_expiry,case when p_installation_date is not null then p_installation_date::timestamptz end,p_actor_id)returning id into a;return a;end$$;
create or replace function maintenance_create_component(p_organization_id uuid,p_parent_asset_id uuid,p_component_prefix_id uuid,p_name text,p_manufacturer text,p_model text,p_serial_number text,p_description text,p_criticality text,p_status text,p_installation_date date,p_actor_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare pc text;p text;n integer;code text;a uuid;begin if not exists(select 1 from maintenance_members where organization_id=p_organization_id and user_id=p_actor_id and active and role in('admin','maintenance'))then raise exception'Maintenance permission denied';end if;select asset_code into pc from maintenance_assets where id=p_parent_asset_id and organization_id=p_organization_id and active for share;select prefix into p from maintenance_component_prefixes where id=p_component_prefix_id and organization_id=p_organization_id and active for share;if pc is null or p is null then raise exception'Invalid parent or component prefix';end if;insert into maintenance_component_code_sequences values(p_organization_id,p_parent_asset_id,p,0,now())on conflict do nothing;update maintenance_component_code_sequences set last_number=last_number+1,updated_at=now()where organization_id=p_organization_id and parent_asset_id=p_parent_asset_id and component_prefix=p returning last_number into n;if n>99 then raise exception'Component sequence exhausted';end if;code:=pc||'-'||p||'-'||lpad(n::text,2,'0');insert into maintenance_assets(organization_id,asset_code,name,asset_name,parent_asset_id,manufacturer,model,serial_number,description,criticality,status,installation_date,installed_at,created_by)values(p_organization_id,code,p_name,p_name,p_parent_asset_id,nullif(trim(p_manufacturer),''),nullif(trim(p_model),''),nullif(trim(p_serial_number),''),nullif(trim(p_description),''),p_criticality,p_status,p_installation_date,case when p_installation_date is not null then p_installation_date::timestamptz end,p_actor_id)returning id into a;return a;end$$;
create or replace view maintenance_asset_code_reconciliation as select id,organization_id,name current_name,asset_code current_code,null::text suggested_new_code,case when asset_code ~ '^[A-Z]{2,5}-[0-9]{3}(-[A-Z]{2,4}-[0-9]{2})?$'then null else'INVALID_FORMAT'end conflict from maintenance_assets;
create index if not exists maintenance_asset_parent_idx on maintenance_assets(organization_id,parent_asset_id);create index if not exists maintenance_asset_search_idx on maintenance_assets(organization_id,asset_code,name,serial_number);
alter table maintenance_asset_categories enable row level security;alter table maintenance_asset_prefixes enable row level security;alter table maintenance_component_prefixes enable row level security;alter table maintenance_asset_code_sequences enable row level security;alter table maintenance_component_code_sequences enable row level security;revoke all on maintenance_asset_categories,maintenance_asset_prefixes,maintenance_component_prefixes,maintenance_asset_code_sequences,maintenance_component_code_sequences from anon,authenticated;grant all on maintenance_asset_categories,maintenance_asset_prefixes,maintenance_component_prefixes,maintenance_asset_code_sequences,maintenance_component_code_sequences to service_role;grant select on maintenance_asset_code_reconciliation to service_role;
